define(['jquery', 'mage/smart-keyboard-handler', 'slick', 'mage/mage', 'domReady!'], function($, keyboardHandler, slick) {
    'use strict';
    keyboardHandler.apply();
    $(document).ready(function() {
        $(window).scroll(function() {
            if ($('.catalog-product-view').length != 0) {
                if ($('.catalog-product-view').offset().top - $(window).scrollTop() <= -20) {
                    $('.product-info-main .box-tocart').addClass("sticky-visible-addtocart").addClass("sticky-visible-addtocart-animation");
                } else {
                    $('.product-info-main .box-tocart').removeClass("sticky-visible-addtocart").removeClass("sticky-visible-addtocart-animation");
                }
            }
        });
        $('.home-page-cat-slider .pagebuilder-column-line').slick({
            slidesToShow: 3,
            infinite: false,
            slidesToScroll: 1,
            autoplay: false,
            dots: true,
            arrows: true,
            responsive: [{
                breakpoint: 1180,
                settings: {
                    slidesToShow: 3
                }
            }, {
                breakpoint: 990,
                settings: {
                    arrows: false,
                    slidesToShow: 2
                }
            }, {
                breakpoint: 480,
                settings: {
                    arrows: false,
                    slidesToShow: 1
                }
            }]
        });
        $('.home-review-slider .pagebuilder-column-line').slick({
            slidesToShow: 3,
            infinite: false,
            slidesToScroll: 1,
            autoplay: false,
            dots: true,
            arrows: true,
            responsive: [{
                breakpoint: 1180,
                settings: {
                    slidesToShow: 3
                }
            }, {
                breakpoint: 990,
                settings: {
                    arrows: false,
                    slidesToShow: 2
                }
            }, {
                breakpoint: 480,
                settings: {
                    arrows: false,
                    slidesToShow: 1
                }
            }]
        });
        $('.home-blog .pagebuilder-column-line').slick({
            slidesToShow: 4,
            infinite: false,
            slidesToScroll: 1,
            autoplay: false,
            dots: true,
            arrows: true,
            responsive: [{
                breakpoint: 1180,
                settings: {
                    slidesToShow: 4
                }
            }, {
                breakpoint: 990,
                settings: {
                    arrows: false,
                    slidesToShow: 3
                }
            }, {
                breakpoint: 480,
                settings: {
                    arrows: false,
                    slidesToShow: 1
                }
            }]
        });
        $('.home-store-slider .pagebuilder-column-line').slick({
            slidesToShow: 9,
            infinite: false,
            slidesToScroll: 9,
            autoplay: false,
            dots: true,
            arrows: true,
            responsive: [{
                breakpoint: 1180,
                settings: {
                    slidesToShow: 9,
                    slidesToScroll: 9,
                }
            }, {
                breakpoint: 990,
                settings: {
                    arrows: false,
                    slidesToShow: 5,
                    slidesToScroll: 5,
                }
            }, {
                breakpoint: 480,
                settings: {
                    arrows: false,
                    slidesToShow: 3,
                    slidesToScroll: 3,
                }
            }]
        });
        $('.influencers-section-block .pagebuilder-column-line').slick({
            slidesToShow: 4,
            infinite: false,
            slidesToScroll: 1,
            autoplay: false,
            dots: true,
            arrows: true,
            responsive: [{
                breakpoint: 1180,
                settings: {
                    slidesToShow: 4
                }
            }, {
                breakpoint: 990,
                settings: {
                    arrows: false,
                    slidesToShow: 3
                }
            }, {
                breakpoint: 480,
                settings: {
                    arrows: false,
                    slidesToShow: 2
                }
            }]
        });
        $('.top_categories_search .footer_head').on('click', function(e) {
            e.preventDefault();
            var accordion = $(this);
            var accordionContent = accordion.next('.top_categories_search ul');
            $('.top_categories_search .footer_head').not(accordion).removeClass("open");
            $('.top_categories_search .footer_head').not(accordion).find('.icon').text('+');
            $('.top_categories_search ul').not(accordionContent).slideUp(250);
            accordion.toggleClass("open");
            accordionContent.slideToggle(250);
            if (accordion.hasClass('open')) {
                accordion.find('.icon').text('-');
            } else {
                accordion.find('.icon').text('+');
            }
        });
    });
});